<?php declare(strict_types=1); use App\Admin\DTO\CompanyAdminFormData; require __DIR__.'/admin-empresa-action-common.php'; admin_empresa_post(); [$app,$session,$user]=admin_empresa_context(); try{$app->companyAdmin()->create(CompanyAdminFormData::fromArray($_POST),$user->id());$session->flash('success','Empresa cadastrada com sucesso.');}catch(InvalidArgumentException $e){$session->flash('danger',$e->getMessage());}catch(Throwable $e){error_log('Company create failed: '.get_class($e));$session->flash('danger','Não foi possível cadastrar a empresa.');}admin_empresa_redirect($app);
